"""Add a Profit Margin (%) column to sales_data.xlsx using Excel formulas."""
import sys
from openpyxl import load_workbook
from openpyxl.styles import Font, Alignment

path = sys.argv[1] if len(sys.argv) > 1 else "sales_data.xlsx"
wb = load_workbook(path)
ws = wb.active

# Locate header row by scanning the first rows for known business terms
header_row = None
headers = {}
for r in range(1, min(ws.max_row, 10) + 1):
    terms = [str(c.value).strip().lower() for c in ws[r] if isinstance(c.value, str)]
    if any(t in " ".join(terms) for t in ("profit", "revenue", "sales", "cost")):
        header_row = r
        for c in ws[r]:
            if isinstance(c.value, str) and c.value.strip():
                headers[c.value.strip().lower()] = c.column
        break
if header_row is None:
    raise SystemExit("no recognizable header row found")
print("header_row:", header_row)
print("headers:", headers)

def find_any(*needles):
    for needle in needles:
        for key, col in headers.items():
            if needle in key:
                return col
    return None

profit_col = find_any("net income", "profit")
revenue_col = find_any("revenue", "sales")
cost_col = find_any("cogs", "cost", "expense")

if revenue_col is None:
    raise SystemExit("no revenue/sales column found")
if profit_col is not None:
    kind = "profit"
elif cost_col is not None:
    kind = "cost"
else:
    raise SystemExit("neither profit nor cost column found to derive margin")

# Reuse an existing Profit Margin column if present, else append a new one
new_col = None
for key, col in headers.items():
    if "margin" in key or "profit margin" in key:
        new_col = col
        break
if new_col is None:
    new_col = ws.max_column + 1
    ws.cell(row=header_row, column=new_col, value="Profit Margin (%)")
    ws.cell(row=header_row, column=new_col).font = Font(bold=True)
    ws.cell(row=header_row, column=new_col).alignment = Alignment(horizontal="center")

def letter(col):
    s = ""
    while col > 0:
        col, rem = divmod(col - 1, 26)
        s = chr(65 + rem) + s
    return s

Lp = letter(profit_col) if profit_col else None
Lr = letter(revenue_col)
Lc = letter(cost_col) if cost_col else None

count = 0
for r in range(header_row + 1, ws.max_row + 1):
    row_has_data = any(ws.cell(row=r, column=c).value is not None
                       for c in range(1, max(ws.max_column, new_col) + 1) if c != new_col)
    if not row_has_data:
        continue
    if kind == "profit":
        formula = f"=IFERROR({Lp}{r}/{Lr}{r},\"\")"
    else:
        formula = f"=IFERROR(({Lr}{r}-{Lc}{r})/{Lr}{r},\"\")"
    cell = ws.cell(row=r, column=new_col, value=formula)
    cell.number_format = "0.0%"
    count += 1

wb.save(path)
print(f"kind={kind} revenue_col={Lr} new_col={letter(new_col)} rows_formulated={count}")

"""Add a Profit Margin (%) column to sales_data.xlsx using Excel formulas.

The new column is computed with worksheet formulas referencing the workbook's
existing Revenue/Profit (or Revenue/Cost) columns so the file stays dynamic.
"""
import copy
import sys

from openpyxl import load_workbook

path = sys.argv[1] if len(sys.argv) > 1 else "sales_data.xlsx"

REV_KEYWORDS = ("revenue", "sales", "turnover")
COST_KEYWORDS = ("cost", "cogs", "expense", "goods_sold")
PROFIT_KEYWORDS = ("profit", "income", "earnings")
MARGIN_KEYWORDS = ("margin",)

MARGIN_HEADER = "Profit Margin (%)"


def norm(value):
    if value is None:
        return ""
    text = str(value).strip().lower()
    for ch in "$(),%_- ":
        text = text.replace(ch, "")
    return text


def contains(header, keywords):
    key = norm(header)
    return any(kw in key for kw in keywords)


def classify(header):
    if contains(header, MARGIN_KEYWORDS):
        return "margin"
    if contains(header, REV_KEYWORDS):
        return "revenue"
    if contains(header, PROFIT_KEYWORDS):
        return "profit"
    if contains(header, COST_KEYWORDS):
        return "cost"
    return None


def as_number(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip().replace(",", "").replace("$", ""))
        except ValueError:
            return None
    return None


wb = load_workbook(path)
ws = wb.active

candidates = []
for r in range(1, min(ws.max_row, 15) + 1):
    rev_c = profit_c = cost_c = margin_c = None
    for c in range(1, ws.max_column + 1):
        v = ws.cell(row=r, column=c).value
        if v is None:
            continue
        kind = classify(v)
        if kind == "revenue" and rev_c is None:
            rev_c = c
        elif kind == "profit" and profit_c is None:
            profit_c = c
        elif kind == "cost" and cost_c is None:
            cost_c = c
        elif kind == "margin" and margin_c is None:
            margin_c = c
    if rev_c is not None:
        candidates.append((r, rev_c, profit_c, cost_c, margin_c))

header_row = revenue_col = profit_col = cost_col = margin_col = None
for cand in candidates:
    r, rev_c, profit_c, cost_c, margin_c = cand
    if as_number(ws.cell(row=r + 1, column=rev_c).value) is not None:
        header_row, revenue_col, profit_col, cost_col, margin_col = cand
        break
if header_row is None and candidates:
    header_row, revenue_col, profit_col, cost_col, margin_col = candidates[-1]

if header_row is None:
    raise SystemExit("ERROR: no Revenue/Sales header found in the first 15 rows")

source_col = profit_col if profit_col is not None else cost_col
if source_col is None:
    raise SystemExit("ERROR: no Profit or Cost column found to compute profit margin")

last_header_col = 1
for c in range(1, ws.max_column + 1):
    if ws.cell(row=header_row, column=c).value is not None:
        last_header_col = c
if margin_col is None:
    margin_col = last_header_col + 1

header_cell = ws.cell(row=header_row, column=margin_col)
header_cell._style = copy.copy(ws.cell(row=header_row, column=revenue_col)._style)
header_cell.value = MARGIN_HEADER

formula_count = 0
for r in range(header_row + 1, ws.max_row + 1):
    rev_val = as_number(ws.cell(row=r, column=revenue_col).value)
    if rev_val is None or rev_val == 0:
        continue
    if as_number(ws.cell(row=r, column=source_col).value) is None:
        continue
    rev_ref = ws.cell(row=r, column=revenue_col).coordinate
    cell = ws.cell(row=r, column=margin_col)
    cell._style = copy.copy(ws.cell(row=r, column=revenue_col)._style)
    cell.number_format = "0.0%"
